  ('25afa757-6625-5e2e-956c-43413c7921da', null, (select id from public.skills where slug = 'write-g8-writing-with-evidence'), null, 'easy',
   $q$Why should the writer remove sentence 9?$q$, $q$[{"text":"It is about honey, which does not relate to the solitary bees the draft analyzes.","is_correct":true},{"text":"It quotes Park's article but does not explain the quotation.","is_correct":false,"misconception_token":"misidentifies-problem"},{"text":"It is the main claim, so it should be moved to the start of the draft.","is_correct":false,"misconception_token":"misidentifies-claim"},{"text":"It repeats the result about the bee hotel from sentence 8.","is_correct":false,"misconception_token":"misreads-repetition"}]$q$::jsonb, $q$It is about honey, which does not relate to the solitary bees the draft analyzes.$q$, $q$The draft is about bees that live alone and do not make hives, so a fact about honey does not support it. Sentence 9 is not a quotation and says nothing about the bee hotel.$q$, 'draft', '362be4b9-3af6-5c86-8e57-b3f540a62e51')
