  ('fc461975-2cb7-5ff6-9f55-cb9ebff60273', null, (select id from public.skills where slug = 'write-g8-writing-with-evidence'), null, 'hard',
   $q$Which sentence would best fill blank 11 as a conclusion to the draft?$q$, $q$[{"text":"Everyone should stop eating honey right away so that the solitary bees can be protected.","is_correct":false,"misconception_token":"unsupported-recommendation"},{"text":"Park's facts about gentle, efficient bees and the class's bee hotel show that these overlooked insects matter and are easy to support.","is_correct":true},{"text":"Park's facts show that most bees live together in hives and make honey for people.","is_correct":false,"misconception_token":"contradicts-source"},{"text":"Park's facts show that mason bees are better than honeybees in every possible way.","is_correct":false,"misconception_token":"overstates-evidence"}]$q$::jsonb, $q$Park's facts about gentle, efficient bees and the class's bee hotel show that these overlooked insects matter and are easy to support.$q$, $q$The choice about gentle, efficient bees and the bee hotel connects evidence from both paragraphs back to the claim. Park compares mason bees and honeybees only on pollination, so saying mason bees are better "in every possible way" goes beyond the evidence.$q$, 'draft', '362be4b9-3af6-5c86-8e57-b3f540a62e51')
