  ('107bc754-f471-59c1-af7a-df9ab9431f9f', null, (select id from public.skills where slug = 'write-g8-writing-with-evidence'), null, 'medium',
   $q$Which sentence best fills blank 6 by explaining the quotation in sentence 5?$q$, $q$[{"text":"In Pine Hollow County, the sun rises very early during the summer months.","is_correct":false,"misconception_token":"off-topic-fact"},{"text":"Ms. Nwosu is a science teacher who works in one of the county schools.","is_correct":false,"misconception_token":"restates-fact"},{"text":"Students arriving that early shows how eager they were for hands-on science they could not get at school.","is_correct":true},{"text":"This shows that the bus driver must have arrived late every single time.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$Students arriving that early shows how eager they were for hands-on science they could not get at school.$q$, $q$The choice "Students arriving that early shows how eager they were" explains what lining up before sunrise reveals and ties it to the claim in sentence 2. Nothing in the article suggests the driver was late, so that choice is a guess.$q$, 'draft', 'f10969c8-3da3-54c7-a142-f56f2f62264c')
